import { Table, StringColumn, TranslatedFieldColumn, IntegerColumn, GuidColumn } from '@servicenow/sdk/core'

export const sys_perspective = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Menu List',
    name: 'sys_perspective',
    schema: {
        applications: StringColumn({
            array: true,
            label: 'Applications',
        }),
        name: TranslatedFieldColumn({
            label: 'Name',
        }),
        roles: StringColumn({
            array: true,
            attributes: {
                record_watcher_blacklist: true,
            },
            label: 'Roles',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        application: StringColumn({
            label: 'Application',
        }),
    },
    textIndex: true,
})
